-- 115: Ekonomika – přenos příjmů z Google tabulky „Příjmy 2026“ (stav 15. 11. 2026).
-- Jen vkládá řádky do economy_entries; dá se spustit opakovaně (nic se nezdvojí).
BEGIN;
DO $$ BEGIN
  IF current_setting('neon.timeline_id', true) IS DISTINCT FROM '70a96b3677653646e65343cae8e27182' THEN
    RAISE EXCEPTION 'Špatná větev';
  END IF;
END $$;
ON CONFLICT (source, source_ref) DO NOTHING;
COMMIT;
SELECT count(*) AS prijmu, sum(amount_hal)/100.0 AS celkem_kc FROM economy_entries WHERE kind = 'income' AND source = 'import';
